"""Armenian text for the Rule page. TEXT = {key: translated inner HTML}."""
TEXT = {
"k34706326": "Աղօթքի կանոնի մասին",
"kc1ba8633": "Ինչ կ'ըսեն Եկեղեցւոյ աղբիւրները՝ որքան աղօթելու մասին, եւ իւրաքանչիւրին կարողութեան չափով աղօթելու մասին։ Այս էջը կը փոխանցէ այդ աղբիւրները. անոնց խրատ չ'աւելցներ։",
"ka7965ff8": "<strong>Նախ ասիկա կարդացէք։</strong> Plithos-ի մէջ եղած ամէն բան տեղեկատու է, ոչ թէ ձեզ չափող կշիռ։ Աղօթքները, պահքի կանոնը, ժամերը եւ արարողութեանց կարգերը հոս ամբողջութեամբ դրուած են, որովհետեւ անոնք Եկեղեցւոյ ժառանգութիւնն են եւ պէտք է ամէնուն հասանելի ըլլան։ Ամբողջութեամբ դնելը չի նշանակեր ըսել՝ թէ որեւէ մէկը պարտաւոր է այդ ամէնը պահել։",
"kef5c7431": "Ձեր պահած կանոնը կը սահմանէ ձեր հոգեւոր հայրը՝ ձեր գիտութեան, ձեր կարողութեան եւ ձեր պարագաներուն համեմատ։ Այս կայքին մէջ ոչ մէկ բան կը գերազանցէ ատիկա, եւ հոս ոչ մէկ բան դատաստան է անոր վրայ՝ որ տպուածէն նուազ կ'աղօթէ։ Ան որ Հայր Մերը օրը երեք անգամ կ'ըսէ եւ սրտով կ'ըսէ, կը պահէ այն կանոնը, որ Եկեղեցին տուաւ առաջին դարուն։",
"kfd250c56": "Այս էջը կը փոխանցէ ինչ որ աղբիւրները կ'ըսեն եւ իր խրատը չ'աւելցներ։ Հոն ուր նախադասութիւն մը յղում չի կրեր, ան այս կայքին մասին ըսուած է, ոչ թէ ձեր աղօթքին ուղղուած ցուցմունք։ Առաջնորդութիւնը ձեր քահանային կը պատկանի, որ ձեր կեանքը գիտէ. այս կայքը զայն չի գիտեր։",
"kd06d4f8a": "Ի՞նչ էր իրապէս ամենահին կանոնը",
"kc90dad01": "Պահպանուած ամենահին քրիստոնէական գործնական ձեռնարկը Դիդախէն է, մօտաւորապէս 100 թուականէն։ Անոր աղօթքի կանոնը օրը երեք անգամ Հայր Մերն է։",
"kadda83fe": "Օրը երեք անգամ այսպէս աղօթեցէք։",
"k513c7122": "Դիդախէ 8 &middot; թրգմ. M. B. Riddle, 1886 &middot; <a href=\"plithos_reader.html#work=didache\">կարդալ Գրադարանին մէջ</a>",
"k355facce": "Նոյն գրութիւնը, երկու գլուխ առաջ, ուղղակիօրէն կը յայտնէ չափի սկզբունքը, եւ ասիկա արդի մեղմացում չէ, այլ ամենահինն է՝ որ Եկեղեցին այս մասին գրած է․",
"k0133b448": "Զի եթէ կրնաս Տէրոջ ամբողջ լուծը կրել, կատարեալ պիտի ըլլաս. իսկ եթէ չես կրնար, ըրէ՛ ինչ որ կրնաս։",
"kec4ccf0b": "Դիդախէ 6 &middot; թրգմ. M. B. Riddle, 1886 &middot; <a href=\"plithos_reader.html#work=didache\">կարդալ Գրադարանին մէջ</a>",
"ka800cdac": "Յետագայ աղօթագիրքերու աւելի ամբողջական աղօթքի կարգերը ասկէ ետք ձեւաւորուեցան։ Դիդախէն պարզապէս ամենահին գրաւոր կանոնն է՝ որ Եկեղեցին ունի, եւ ահա ինչ կը պահանջէ ան։",
"kc8529ac1": "Քանակը չափ չէ",
"k605c07f5": "Սուրբ Յովհան Կասիանոս, հինգերորդ դարու սկիզբը եգիպտացի հայրերու ուսուցումը արձանագրելով, կ'զգուշացնէ աղօթքը այն ժամերով հաշուելէ, զորս մարդ յատկապէս անոր կը յատկացնէ․",
"kda219ca8": "Քանզի շատ քիչ կ'աղօթէ ան, որ սովորած է աղօթել միայն այն ժամերուն, երբ ծունկ կը կրկնէ։",
"k87ef1fff": "Սուրբ Յովհան Կասիանոս, Խօսակցութիւններ 10.14 &middot; թրգմ. Edgar C. S. Gibson &middot; <a href=\"plithos_reader.html#work=cassian-conferences\">կարդալ Գրադարանին մէջ</a>",
"k6f06dcb5": "Ուրեմն Կասիանոսի մօտ աղօթքի չափը որոշուած ժամերէն աւելի լայն է, եւ խօսքը ուղղուած է անոնց, որ զայն այդ ժամերուն մէջ կը փակեն։ Ան չէ որ այս միտքը կը մտցնէ։ Առաքեալը արդէն տուած էր կանոնը այնպիսի ձեւով, զոր ոչ մէկ ժամացոյց կը պարունակէ․",
"k9d16dd79": "Ամէն ատեն աղօթեցէ՛ք Հոգիով՝ ամէն տեսակ աղօթքով եւ աղերսանքով: Հսկեցէ՛ք ասոր վրայ բոլորովին յարատեւութեամբ ու աղերսանքով՝ բոլոր սուրբերուն համար.",
"kd45e4afe": "Եփեսացիս 6:18",
"k8ff6957a": "Եւ աւելի կարճ․ <em>անդադար աղօթեցէք</em> (Ա Թեսաղոնիկեցիս 5:17)։ Որոշուած ժամերու կանոնը ատոր կը ծառայէ. զայն չի սպառեր։",
"k94022491": "Կարգ մը, ոչ թէ սանդուխ",
"k6f5ac9c2": "Ինչ որ կը հետեւի՝ Plithos-ի սահմանած աստիճաններ չեն։ Ասիկա կարգ մըն է այն բանին, զոր աղբիւրները եւ ընդունուած գիրքերը կը պարունակեն, ըստ այն չափին՝ որ իւրաքանչիւրը կը խնդրէ օրէն։ <strong>Ասոնցմէ որը կը վերաբերի տուեալ անձի, հարցում է իր հոգեւոր հօրը, ոչ թէ այս էջին։</strong>",
"kbd0070ec": "Ասիկա սանդուխ չէ, եւ առաջին կէտը հէնց ատոր պատճառն է։ Յիսուսի աղօթքը առաջին կը կենայ, որովհետեւ ամենէն քիչը կը խնդրէ մարդուն պարագաներէն, ոչ թէ որովհետեւ ամենէն քիչը կը խնդրէ մարդէն։ Նոյն այդ աղօթքն է՝ զոր հեզաստ հայրերը կ'անուանեն աղօթքին ամբողջութիւնը, եւ զոր ամենէն յառաջացածներուն կը տրուի՝ գրուած ամէն բանի փոխարէն։ Ան երկու ծայրերուն վրայ միանգամայն կը կենայ։",
"kec53651e": "Յիսուսի աղօթքը",
"kd76e85df": "Երբ ո՛չ ժամանակ կայ, ո՛չ գիրք, ո՛չ լռութիւն - ճամբուն վրայ, գործի, հիւանդութեան մէջ, երբ ո՛չ կանգնիլ կրնաս, ո՛չ ձայնով խօսիլ",
"k15c8fcc6": "Յիսուսի աղօթքը իր ամբողջական ձեւով․ <em>Տէր Յիսուս Քրիստոս, Որդի Աստուծոյ, ողորմէ՛ ինծի՝ մեղաւորիս։</em> Հոն ուր ատիկա ալ շատ է, Հայրերը կ'արտօնեն աւելի կարճ ձեւեր՝ <em>Տէր Յիսուս Քրիստոս, ողորմէ՛ ինծի</em>, կամ պարզապէս <em>Տէր, ողորմեա՛</em>։ Ան ո՛չ գիրք կ'ուզէ, ո՛չ կանգնիլ, ո՛չ ձայն, եւ կրնայ կրուիլ սովորական աշխատանքային օրուան ընթացքին։",
"k433c6e1a": "<a href=\"prayers.html#s=heart\">Յիսուսի աղօթքը եւ Հայրերու խրատը՝ զայն պահելու մասին</a>",
"k0607d349": "Ան առաջին կու գայ, որովհետեւ ամէն պարագայի կը մնայ, ոչ թէ որովհետեւ հոս եղածներուն ամենափոքրն է։ Կասիանոս, Խօսակցութիւններ 10.14․ \"շատ քիչ կ'աղօթէ ան, որ սովորած է աղօթել միայն այն ժամերուն, երբ ծունկ կը կրկնէ։\"",
"k4fbd7571": "Հայր Մերը, օրը երեք անգամ",
"kccf34183": "Որոշուած կանոն որոշուած ժամերու, երբ ատիկա կարելի է",
"k6c98a369": "Մեր ունեցած ամենահին քրիստոնէական ձեռնարկին կանոնը։ Փոքր կանոն է, բայց որոշուած ժամերու կանոն է, եւ ուստի կտրտուած օրէն աւելի կը խնդրէ՝ քան Յիսուսի աղօթքը։",
"kb80095bf": "Դիդախէ 8։",
"k73f947ac": "Սարովցի սուրբ Սերափիմի կանոնը",
"kbeb11458": "Անոնց համար, որոնց աշխատանքը աւելի երկար կանոնի տեղ չի ձգեր",
"kba90cd4c": "Արթննալէն ետք, պատկերներուն առջեւ կանգնած․ Հայր Մերը երեք անգամ, <em>Աստուածածին Կոյս, ուրախացի՛ր</em> երեք անգամ, եւ Հաւատոյ Հանգանակը մէկ անգամ։ Ապա գործի, ամբողջ առաւօտ լռելեայն Յիսուսի աղօթքը ըսելով, եւ կէսօրէ ետք՝ <em>Ամենասուրբ Աստուածածին, փրկէ՛ զիս</em>։ Նոյն կարճ կանոնը դարձեալ քնանալէ առաջ։",
"k6464f90a": "Սուրբ Սերափիմ զայն տուաւ բանուորներու եւ ընտանիքի հայրերու, որոնք չէին կրնար պահել աւելի ամբողջական առաւօտեան եւ երեկոյեան աղօթքները, եւ զայն չհամարեց զիջում մը՝ որմէ պէտք է դուրս գալ։ Ասիկա որոշուած ժամերու որոշուած աղօթքներու կանոն է՝ միացած աղօթքի մը, որ կ'անցնի աշխատանքային օրուան մէջէն, եւ ահա թէ ինչու հոս կը կենայ եւ ոչ թէ աւելի վար։",
"kc823332f": "Սարովցի սուրբ Սերափիմ, աշխարհականներուն ուղղուած իր խրատներուն մէջ։ Աղօթքները իրենք Աղօթքներու էջին վրայ են։",
"k3041ac63": "Առաւօտ եւ երեկոյ",
"k225e3ccd": "Աղօթագիրքի սովորական կանոնը՝ աշխարհականին համար",
"kf4d2a2e5": "Առաւօտեան աղօթքները արթննալու ատեն եւ երեկոյեան աղօթքները քնանալէ առաջ, ուշադրութեամբ ըսուած եւ ոչ թէ շտապով անցուցած։",
"k98ad4446": "<a href=\"prayers.html#s=daily\">Առաւօտեան եւ երեկոյեան աղօթքներ</a>",
"k8ad36869": "Սուրբ Թէոփան Մեկուսեալ աղօթագիրքի առաւօտեան եւ երեկոյեան աղօթքները բոլորովին բաւարար կը համարէր սկսող աշխարհականին համար։ Տես նշումը Աղօթքներու էջին վրայ՝ աւելի ամբողջական խրատին համար։",
"k4cecadd4": "Ժամերուն հետ",
"kefb7d0a1": "Հոն ուր օրը կ'արտօնէ",
"k8fb45542": "Օրուան ընթացքին կարճ արարողութիւնները, Առաջին Ժամէն մինչեւ Հանգստեան ժամը։",
"k6b300612": "<a href=\"prayers.html#s=hours\">Ժամերը</a>",
"k61610f0a": "Դիդախէի օրական երեք աղօթքները այս շրջանակին սերմն են։ Ամբողջական Ժամերը տրուած են Ժամագիրքին մէջ։",
"kb3c5ab3d": "Հաղորդութեան պատրաստութիւն",
"k8dbdf873": "Խորհուրդները ընդունելէ առաջ",
"kced3fbfd": "Պատրաստութեան կարգը, բաժակին առջեւ ըսուող երկու աղօթքները, եւ անոնցմէ ետք գոհաբանութիւնը։ Կարգէն որքանը կ'ըսուի, եւ արդեօք նախորդ երեկոյին կը պահուի թէ նոյն առաւօտ, կը տարբերի ըստ աւանդութեան եւ կը սահմանուի հոգեւոր հօրմէ։ Տես ստորեւ՝ ինչ որ Հայրերը կը դնեն որպէս մօտենալու իրական պայման։",
"k8f37e928": "<a href=\"prayers.html#s=communion\">Սուրբ Հաղորդութեան աղօթքները, իրենց երեք մասերով</a>",
"k88dda4ec": "Գործադրութիւնը զգալիօրէն կը տարբերի սլաւոնական եւ յունական աւանդութիւններուն միջեւ, թէ՛ սպասուող պատրաստութեան մէջ եւ թէ՛ հաւատացեալներու հաղորդուելու յաճախականութեան մէջ։",
"ka6cba0b8": "Երբ չէք կրնար ձեր կանոնը պահել",
"k87db3602": "Ճամբորդութիւն, հիւանդութիւն, գիշերային աշխատանք, փոքր զաւակներ, սուգ եւ յոգնութիւն՝ ասոնք բոլորը կը ընդհատեն կանոն մը։ Վերի գրութիւններէն երկուքը ուղղակիօրէն ատոր կը վերաբերին։",
"k8dcf4ab6": "<strong>Դիդախէն կանոնը չի ներկայացներ որպէս ամէն բան կամ ոչինչ։</strong> Անոր ցուցմունքը այն չէ՝ որ ամբողջ լուծը կրես կամ ոչինչ, այլ այն՝ որ հոն ուր ամբողջը չի կրնար կրուիլ, \"ըրէ՛ ինչ որ կրնաս\"։",
"ka4ac033d": "<strong>Աղօթքը կանգնելու ժամերուն մէջ փակուած չէ։</strong> Ասիկա է վերի Կասիանոսի խօսքին ուժը․ ան կը կշտամբէ անոնք, որ իրենց աղօթքը կը հաշուեն միայն ծունկ կրկնելու ժամերով, եւ ատիկա այդ ժամերէն դուրս եղած աղօթքը հաշիւին մէջ կը մտցնէ եւ ոչ թէ անկէ դուրս կը հանէ։ Յիսուսի աղօթքը իր ընդունուած կարճ ձեւերով ո՛չ գիրք կը պահանջէ, ո՛չ մարմնի դիրք, ո՛չ ձայն։",
"k1c9eeaa9": "Ինչ որ Հայրերը կը դնեն որպէս մօտենալու պայման",
"keac4f2df": "Պատրաստութեան կարգը իրական բարիք է եւ իրական ժառանգութիւն։ Ան չէ որ մարդը ընդունելու կարող կ'ընէ։ Այս մասին Հայրերը ուղղակի կը խօսին, եւ անոնք գրած են շատ առաջ՝ քան որեւէ տպուած պատրաստութեան կարգ գոյութիւն ունենար։",
"kc356b366": "Սուրբ Յովհան Ոսկեբերան, Եբրայեցիներուն նամակին վրայ քարոզելով, կ'առնէ հէնց այն հարցումը՝ թէ որքա՛ն յաճախ եւ որքա՛ն շատ, եւ կը մերժէ ատոր պատասխանել այդ բառերով․",
"kce69ff57": "Ուրեմն ի՞նչ։ Որո՞նք հաւնինք։ Անոնք՝ որ տարին մէկ անգամ կ'ընդունին։ Անոնք՝ որ շատ անգամ կ'ընդունին։ Անոնք՝ որ հազուադէպ կ'ընդունին։ Ո՛չ մէկ անգամ ընդունողները, ո՛չ յաճախ ընդունողները, ո՛չ հազուադէպ ընդունողները, այլ անոնք՝ որ մաքուր խղճով, մաքուր սրտով, անմեղադրելի կեանքով կը մօտենան։ Այդպիսիները թող անդադար մօտենան. իսկ անոնք որ այդպիսի չեն, ո՛չ իսկ մէկ անգամ։",
"k2d880e69": "Սուրբ Յովհան Ոսկեբերան, Ճառ 17 Եբրայեցիներուն վրայ &middot; թրգմ. Frederic Gardiner &middot; <a href=\"plithos_reader.html#work=chrysostom-homilies-hebrews\">կարդալ Գրադարանին մէջ</a>",
"k3448180a": "Ոսկեբերանի նշած չափանիշը խղճի վիճակն է։ Ան թիւ չի նշեր՝ ո՛չ հաղորդութիւններու, ո՛չ նախապէս ըսուած աղօթքներու, եւ յաճախականութեան հարցը մէկ կողմ կը դնէ իբրեւ սխալ հարցում։",
"k4bc3e896": "Սուրբ Յովհան Կասիանոս կ'անդրադառնայ միւս կէսին, եւ գլուխին խորագիրը ատիկա յստակ կ'ըսէ․ <em>թէ թէպէտ կը խոստովանինք որ առանց մեղքի չենք կրնար ըլլալ, այսուհանդերձ պէտք չէ Տէրոջ Հաղորդութենէն հեռանանք։</em>",
"k3620ced2": "Սակայն պէտք չէ Տէրոջ Հաղորդութենէն հեռանանք՝ որովհետեւ մենք զմեզ մեղաւոր կը խոստովանինք, այլ առաւել եւս փութով անոր վազենք՝ մեր հոգիին բժշկութեան եւ մեր ոգիին մաքրութեան համար, եւ առաւելապէս մեր վէրքերուն դեղը փնտռենք՝ մտքի խոնարհութեամբ եւ հաւատքով, մեզ անարժան համարելով այսքան մեծ շնորհք ընդունելու։",
"k99dd8e07": "Այլապէս չենք կրնար արժանաւորապէս ընդունիլ Հաղորդութիւնը՝ ո՛չ իսկ տարին մէկ անգամ, ինչպէս ոմանք կ'ընեն՝ որ վանքերու մէջ կ'ապրին եւ երկնային խորհուրդներու արժանապատուութիւնը, սրբութիւնը եւ արժէքը այնպէս կը դիտեն, որ կը կարծեն թէ սուրբերէն եւ անբիծերէն զատ ոչ ոք պէտք է համարձակի զանոնք ընդունիլ, եւ ոչ թէ առաւել՝ թէ անոնք մեզ սուրբ եւ մաքուր պիտի ընեն ընդունելով։ Եւ ասով իսկ կ'իյնան աւելի մեծ ինքնահաւանութեան եւ ամբարտաւանութեան մէջ՝ քան այն, զոր կը կարծեն թէ կը խուսափին, որովհետեւ այն պահուն երբ կ'ընդունին, իրենք զիրենք արժանի կը համարեն ընդունելու։",
"kb8b440b1": "Սուրբ Յովհան Կասիանոս, Խօսակցութիւններ 23.21 &middot; թրգմ. Edgar C. S. Gibson &middot; <a href=\"plithos_reader.html#work=cassian-conferences\">կարդալ Գրադարանին մէջ</a>",
"kcab416e7": "Կասիանոսի փաստը այն է, որ անարժանութեան զգացումէն հեռանալը ինքնին աւելի մեծ ինքնահաւանութիւն է, քանի որ ան որ կը հեռանայ մինչեւ արժանի ըլլայ, կ'ենթադրէ թէ ուրիշ օր մը արժանի պիտի ըլլար։ Ատոր դէմ ան կը դնէ այն, ինչի համար, իր խօսքով, Խորհուրդները կան․ ոչ թէ վարձատրութիւն արդէն մաքուրներուն, այլ միջոց՝ որով, իր բառերով, անոնք մեզ սուրբ եւ մաքուր պիտի ընեն ընդունելով։",
"k1ceaa3c4": "Ինչ որ Եկեղեցին հաղորդուողին բերանը կը դնէ իր մասին",
"k15496498": "Ասիկա չափը իջեցնել չէ։ Ասիկա ի՛նքն է չափը, եւ Եկեղեցին զայն կը դնէ ամէն մօտեցողի բերանը։ Բաժակին առջեւ բարձրաձայն, ամբողջ ժողովուրդին կողմէ ըսուող խոստովանութիւնը չ'ըսեր՝ թէ ըսողը հասած է․",
"kffb87ae9": "Կը հաւատամ, Տէ՛ր, եւ կը խոստովանիմ՝ թէ Դուն ես ճշմարտապէս Քրիստոսը, Որդին կենդանի Աստուծոյ, որ աշխարհ եկար մեղաւորները փրկելու, որոնց առաջինը ես եմ։",
"kd40a122c": "Ընդունելէ առաջ ըսուող աղօթքը &middot; ըստ Ա Տիմոթէոս 1:15 &middot; <a href=\"prayers.html#s=communion\">կարդալ աղօթագիրքին մէջ</a>",
"k91d95d94": "Առաքեալին սեփական խօսքերն են՝ <em>Քրիստոս Յիսուս աշխարհ եկաւ՝ փրկելու մեղաւորները, որոնց գլխաւորը ես եմ</em>, եւ Եկեղեցին զանոնք նամակին մէջ չձգեց։ Զանոնք դրաւ բաժակին առջեւ եւ տուաւ ամէն հաղորդուողի՝ որ առաջին դէմքով ըսէ, այն օրը երբ կ'ընդունի։ Սուրբերը անոնք են, որ այդ նախադասութիւնը ըսին եւ սրտով ըսին, ոչ թէ անոնք՝ որ հասան այնպիսի կէտի, ուր ան այլեւս իրենց չէր վերաբերեր։ Շնորհքը կը տրուի. մեզմէ կը պահանջուի՝ որ պատասխանենք, պահենք մեզի տրուած պատուիրանները, եւ շարունակենք պատասխանել՝ անոնք չպահելէ ետք ալ։",
"kf78cb40a": "Ինչ կը նշանակէ ասիկա գործնականին մէջ",
"k87e5b047": "<strong>Կարգը կանոնական պայմաններուն մէջ չէ։</strong> Եկեղեցւոյ ոչ մէկ կանոն զայն կը պահանջէ ընդունելէ առաջ, եւ որոշուած տպուած յաջորդականութիւնը կանոններէն յետոյ է. անկէ որքանը կ'ըսուի՝ կը սահմանէ հոգեւոր հայրը։",
"k0e542bbd": "<strong>Ինչ որ աւանդութիւնը իրապէս կը նշէ</strong> բաժակին առջեւ՝ խիղճ մը որ չապաշխարուած մեղքի մէջ չի հանգչիր, խաղաղութիւն ընկերոջ հետ, հաղորդութեան պահքը, եւ խոստովանութեան մասին հոգեւոր հօր հնազանդութիւնը։ Կասիանոս ուղղակիօրէն կ'անդրադառնայ անոր պարագային, որ անարժանութեան զգացումով հեռացած է, վերի հատուածին մէջ. Ոսկեբերան կ'անդրադառնայ անոր՝ որ թիւերով կը հաշուէ։",
"k21c606eb": "<strong>Հաղորդութեան պահքը կանոնական է, ոչ թէ սովորութեան։</strong> Ափրիկեան Օրէնսգիրքը զայն կը պահանջէր՝ արտօնելով տարին մէկ բացառութիւն, այն օրը երբ Տէրոջ Ընթրիքը կը յիշատակուի․",
"k253a3d17": "Որ Սեղանին Խորհուրդները չկատարուին բացի պահեցողներէն, բացի Տէրոջ Ընթրիքին յիշատակին տարեկան մէկ օրէն. քանզի եթէ ոմանց ննջեցեալներու, եպիսկոպոսներու կամ ուրիշներու յիշատակը կէսօրէ ետք պէտք է կատարուի, թող կատարուի միայն աղօթքներով, եթէ պաշտօն կատարողները արդէն կերած են։",
"kb289f398": "Ափրիկեան Օրէնսգիրք (419), կանոն 41 &middot; թրգմ. Henry R. Percival, 1900 &middot; <a href=\"plithos_reader.html#work=canons-ecumenical\">կարդալ Գրադարանին մէջ</a>",
"kfd9e4371": "Տրուլլոյի Ժողովը առաւ այդ կանոնը եւ վերցուց բացառութիւնը․",
"k97125890": "Կարթագենի Ժողովին կանոն մը կ'ըսէ, թէ սեղանին սուրբ խորհուրդները չպէտք է կատարուին բացի պահեցողներէն, բացի տարուան մէկ օրէն՝ որուն մէջ Տէրոջ Ընթրիքը կը տօնուի։ Այն ատեն, թերեւս այդ տեղերուն մէջ Եկեղեցւոյ օգտակար որոշ պարագաներու պատճառով, նոյնինքն սուրբ Հայրերը գործածեցին այս թոյլտուութիւնը։ Բայց քանի որ ոչինչ մեզ կը մղէ ձգել ճշգրիտ պահպանութիւնը, կը հրամայենք որ առաքելական եւ հայրապետական աւանդութիւնը հետեւուի. եւ կը սահմանենք թէ ուղիղ չէ Մեծ Պահքի վերջին շաբթուան հինգերորդ օրը պահքը լուծել, եւ այսպէս անարգել ամբողջ Մեծ Պահքը։",
"k5c17110d": "Տրուլլոյի, Հինգ-Վեցերորդ Ժողովը (692), կանոն 29 &middot; թրգմ. Henry R. Percival, 1900 &middot; <a href=\"plithos_reader.html#work=canons-ecumenical\">կարդալ Գրադարանին մէջ</a>",
"k4b650236": "Ինչ որ կանոնները կը պահանջեն՝ պահքն է։ Զայն նախորդ կէսգիշերէն հաշուելը այն սովորութիւնն է որ զայն կը կրէ, եւ ասիկա սովորական գործադրութիւնն է ամէն իրաւասութեան մէջ։ Հոն ուր Պատարագը երեկոյեան կը կատարուի, ինչպէս Նախասրբեալ Ընծաներունը եւ ինչպէս կրնան ըլլալ Ծննդեան, Աստուածայայտնութեան, Աւագ Հինգշաբթիի եւ Աւագ Շաբաթի Պատարագները, ժամանակահատուածը կը սահմանէ եպիսկոպոսը՝ եւ ոչ թէ կէսգիշերէն հաշուելը։ Դեղը որ պէտք է առնուի, հիւանդութիւնը, յղութիւնը, մանկութիւնը եւ խոր ծերութիւնը կը լուծուին հոգեւոր հօրմէ։ Հարցնելը նոյնը չէ ինչ ազատուիլը, եւ ոչ մէկը ասոնցմէ պատճառ է բաժակէն հեռու մնալու։",
"kc182b483": "<strong>Բաժակին առջեւ ըսուող երկու աղօթքները</strong> - \"Կը հաւատամ, Տէր, եւ կը խոստովանիմ\" եւ \"Քու խորհրդաւոր Ընթրիքիդ\" - բարձրաձայն կ'ըսուին ամբողջ ժողովուրդին հետ շատ ծխական եկեղեցիներու մէջ։",
"kaebd6892": "Կանոնները ձեւով վանական են. կեանքը՝ զոր կը խնդրեն, այդպիսի չէ",
"keedea2a4": "Աղօթագիրքի մէջ տպուած գրեթէ ամէն որոշուած կանոն իր ներկայ ձեւը ստացաւ վանքի մը մէջ, եւ ահա թէ ինչու պատրաստութիւնը կրնայ կարդացուիլ այնպէս՝ որպէս թէ ուրիշի ուղղուած ըլլայ։ Առարկութիւնը այնքան հին է, որ սուրբ Յովհան Ոսկեբերան զայն կը դնէ իր ունկնդիրներուն բերանը՝ պատասխանելէ առաջ․",
"k3f765fe1": "Ես վանականներէն չեմ, պիտի ըսես, այլ ունիմ կին ու զաւակներ եւ տան հոգը։ Ահա հէնց ասիկա է որ ամէն բան կործանեց՝ որ դուն կը կարծես թէ աստուածային Գիրքերու ընթերցումը միայն անոնց կը պատկանի, մինչ դուն շատ աւելի կարիք ունիս անոր՝ քան անոնք։ Քանզի անոնք որ աշխարհի մէջ կ'ապրին եւ ամէն օր վէրքեր կ'ընդունին, անոնք ամենէն շատ դեղի կարիք ունին։",
"kebad4fa3": "Սուրբ Յովհան Ոսկեբերան, Ճառ 2 Մատթէոսի վրայ &middot; թրգմ. George Prevost &middot; <a href=\"plithos_reader.html#work=chrysostom-homilies-matthew\">կարդալ Գրադարանին մէջ</a>",
"k5eee983b": "Նոյնը կ'ըսէ կենցաղին մասին ինքնին, եւ կ'ըսէ զայն որպէս մերժում՝ անապատը օրէնք դարձնելու․",
"k00cd498f": "Ես օրէնք չեմ դներ որ լեռներն ու անապատները գրաւէք, այլ որ բարի եւ խոհեմ եւ ողջախոհ ըլլաք՝ քաղաքին մէջտեղը բնակելով։",
"kc7ddce00": "Սուրբ Յովհան Ոսկեբերան, Ճառ 7 Մատթէոսի վրայ &middot; թրգմ. George Prevost &middot; <a href=\"plithos_reader.html#work=chrysostom-homilies-matthew\">կարդալ Գրադարանին մէջ</a>",
"k99a23dda": "Իսկ Հռովմայեցիներուն վրայ ան կ'առնէ այն միտքը՝ թէ սովորական կեանքը պատուիրաններուն սխալ հասցէն է, որպէս մեղադրանք հաւատքին դէմ եւ ոչ թէ որպէս անոր նկարագրութիւն․",
"k91017238": "Քանզի եթէ կարելի չէ որ ան որ քաղաքներու մէջտեղը կ'ապրի աշակերտ ըլլայ, ասիկա ծանր մեղադրանք է այս կենցաղին դէմ, այսինքն թէ պէտք է քաղաքները ձգենք եւ անապատներ վազենք։ Բայց ցոյց տուր ինծի մարդ մը՝ որ ունի կին եւ զաւակներ եւ ընտանիք, եւ այսուհանդերձ իմաստութիւն կը փնտռէ։ Ի՞նչ ըսենք ուրեմն այս ամէնուն։ Չպէ՞տք է գլուխնիս խոնարհեցնենք եւ ամչնանք։ Քանզի Քրիստոս մեզի այդպիսի պատուիրան չտուաւ. այլ ի՞նչ։ Թող ձեր լոյսը փայլի մարդոց առջեւ, ոչ թէ լեռներ եւ անապատներ եւ ամայի եւ հեռաւոր տեղեր։",
"kafb2fb07": "Սուրբ Յովհան Ոսկեբերան, Ճառ 26 Հռովմայեցիներուն վրայ &middot; թրգմ. J. B. Morris եւ W. H. Simcox &middot; <a href=\"plithos_reader.html#work=chrysostom-homilies-romans\">կարդալ Գրադարանին մէջ</a>",
"ke1ee6e3e": "Ան կը զգուշանայ, հէնց յաջորդ նախադասութեան մէջ, որ չկարդացուի իբրեւ վանականները նուաստացնող․ կ'ըսէ թէ կը խօսի \"ոչ թէ նախատելով անոնք որ լեռները առին, այլ ողբալով անոնք որ քաղաքներու մէջ կ'ապրին, որովհետեւ անկէ առաքինութիւնը վտարեցին։\" Վանականը իր կամքը կու տայ ծերունիի մը։ Աշխարհականին նոյն բանը կը տրուի տալու համար՝ ամուսնութեան մէջ, աշխատանքի մը մէջ զոր ինք չընտրեց, համբերութեան մէջ որ տուն մը կ'արժէ, եւ ասիկա իրմէ կը խնդրուի այնպիսի ձեւով, զոր ոչ մէկ կանոն կրնայ նախապէս տպել։",
"ka438020e": "Պահքը, խոստովանութիւնը եւ պատրաստութեան մնացեալը",
"k67ac3841": "Պատրաստութիւնը միայն աղօթք չէ։ Չորեքշաբթիի եւ Ուրբաթի պահքը անոր ամենահին մասն է, եւ ան կը գտնուի Դիդախէի նոյն այն գլուխին մէջ՝ որ աղօթքի կանոնը կու տայ․",
"ke069eea2": "Իսկ ձեր պահքերը թող կեղծաւորներուն հետ չըլլան. քանզի անոնք կը պահեն շաբթուան երկրորդ եւ հինգերորդ օրերը. իսկ դուք պահեցէք չորրորդ օրը եւ Պատրաստութեան օրը (Ուրբաթ)։ Եւ մի՛ աղօթէք ինչպէս կեղծաւորները, այլ ինչպէս Տէրը հրամայեց իր Աւետարանին մէջ, այսպէս աղօթեցէք․ Հայր մեր որ յերկինս ես...",
"k4e4ee152": "Այս հատուածին զգուշացումը կը վերաբերի երկու կէսերուն․ ոչ թէ չպահելուն, այլ <em>կեղծաւորներուն պէս</em> պահելուն, եւ ոչ թէ չաղօթելուն, այլ <em>կեղծաւորներուն պէս</em> աղօթելուն։ Դիդախէն երկու կանոնները մէկ շունչով կու տայ եւ իւրաքանչիւրը նոյն ձեւով կը պայմանաւորէ։",
"k901f0415": "Հաղորդութենէ առաջ խոստովանութիւնը կը սպասուի ոմանց աւանդութեան մէջ եւ ուրիշներու մէջ՝ ոչ, եւ տարբերութիւնը հին է եւ ոչ թէ թուլութեան հարց։ Արժէ զայն ներկայացնել, որովհետեւ ան որ մէկ աւանդութեան մէջ սորվեցաւ պատրաստուիլ եւ ապա միւսին ծխական եկեղեցին գտնուեցաւ, դիւրաւ կրնայ սովորութեան տարբերութիւնը իր վրայ դատաստան համարել։",
"k345e3232": "<strong>Սլաւոնական Եկեղեցիներուն մէջ</strong> - Ռուսական, Արտասահմանեան Ռուսական, Ամերիկայի Ուղղափառ Եկեղեցի, Ուքրանական, Սերբական - խոստովանութիւնը սովորաբար կը սպասուի ամէն հաղորդութենէ առաջ։ Պատրաստութիւնը սովորութեամբ կը ներառէ երեք կանոնները՝ Փրկիչին, Աստուածածինին եւ Պահապան Հրեշտակին, եւ յաճախ Ամենաքաղցր Տէր Յիսուսի Ակաթիստը, աւելի քան պատրաստութեան աղօթքները. եւ նախորդ երեկոյի հսկումին կամ երեկոյեան ժամերգութեան ներկայութիւնը կը սպասուի իբրեւ պատրաստութեան մաս եւ ոչ թէ իբրեւ առանձին բարեպաշտութիւն։",
"k3c46f09c": "<strong>Յունական, Անտիոքեան եւ Ռումանական գործադրութեան մէջ</strong> խոստովանութիւնը աւելի յաճախ բաժնուած է հաղորդութենէն եւ կը պահուի հոգեւոր հօր սահմանած ընդմիջումներով, յաճախ չորս պահքերուն ընթացքին։ Պատրաստութիւնը աւելի յաճախ կը նշանակէ պատրաստութեան աղօթքները՝ քան կանոններու եւ ակաթիստի ամբողջ շարքը, եւ երեկոյեան արարողութիւնը զօրաւոր կերպով կը յանձնարարուի՝ առանց ընդունելութեան պայման դառնալու։",
"kbf226744": "Երկուքն ալ ամբողջ տեղական Եկեղեցիներու հաստատուած գործադրութիւնն են, եւ իւրաքանչիւրը կը պահուի այդ Եկեղեցւոյ հոգեւորականութեան առաջնորդութեան տակ։ Մարդու կանոնը հոս կու գայ իր սեփական հոգեւոր հօրմէն, ոչ թէ այն նկարագրութենէն՝ զոր պատահաբար առաջինը կարդաց։",
"k7edee590": "Վերջին խօսք չափի մասին",
"k95bf9581": "Կանոնը կայ՝ որպէսզի մէկ կողմէ ծուլութեան չտրուինք, միւս կողմէ մեր ուժէն վեր չլարուինք։ Սուրբ Թէոփան Մեկուսեալ կ'ուսուցանէր, թէ ճամբան երկու փոս ունի․ աջին՝ նախանձախնդրութիւն առանց գիտութեան, ձախին՝ ծուլութիւն։ Չափազանցութիւնը սկսողը կը հասցնէ յոգնութեան եւ յուսահատութեան՝ երբ ձախողի, եւ հպարտութեան՝ երբ յաջողի։ Սուրբ Իգնատիոս Բրեանչանինով գրեց, թէ կանոնը քեզի համար կայ. դուն կանոնին համար չես, այլ Տէրոջ համար կ'ապրիս, եւ պէտք է պահես զանազանութեան ազատութիւնը։",
"kd192a6bd": "Սկսէ քիչով։ Աւելի լաւ է քիչ աղօթք ըսել ուշադրութեամբ՝ քան շտապով շատերու մէջէն անցնիլ։ Եթէ հոգեւոր հայր ունիս, պահէ այն կանոնը զոր ան կու տայ եւ ոչինչ փոխէ առանց իր օրհնութեան. եթէ տակաւին չունիս, պահէ չափաւոր կանոն մը՝ քու ուժիդ համապատասխան, եւ փնտռէ այդպիսի հայր մը։ Ոչ մէկ գիրք եւ ոչ մէկ էջ կրնայ գրաւել Քրիստոսի մէջ կենդանի հօր տեղը։",
"kb6eb659b": "Առնուած է սուրբ Թէոփան Մեկուսեալէն, Աղօթքի կանոն, եւ սուրբ Իգնատիոսէն (Բրեանչանինով) աղօթքի կանոնի մասին &middot; <a href=\"index.html#guide\">նաեւ Ուղեցոյցին մէջ</a>",
"keda0cc2f": "Այս կայքին մէջ ոչինչ կշիռ է՝ որուն վրայ որեւէ մէկը կը կշռուի։ Ասիկա գրադարան է եւ տոմար։",
"kc89cd31d": "Աղոթքի կանոնը աղոթքի որոշակի չափ է, որ պահվում է որոշակի ժամերին։ Այս էջը շարադրում է, թե ինչ են ասում Եկեղեցու աղբյուրները չափի մասին, և ինչ ձևեր է սովորաբար ստանում կանոնը։",
"k36c2948e": "<strong>Նախ սա կարդացեք։</strong> Այն կանոնը, որ պահում եք, սահմանում է ձեր հոգևոր հայրը՝ ըստ ձեր ուժի և հանգամանքների։ Այստեղ տպվածը ժառանգությունն է, ոչ թե չափ, որով որևէ մեկը դատվում է։ Ով օրը երեք անգամ ասում է Հայր մերը և անկեղծորեն ասում է, նա պահում է այն կանոնը, որ Եկեղեցին տվեց առաջին դարում։",
"k530f73b4": "Որտեղից է գալիս կանոնը",
"kc776efc1": "Երկու գլուխ առաջ նույն գրվածքը նշում է չափը, և դա ամենահինն է, ինչ Եկեղեցին գրի է առել այս մասին.",
"k81f4ff1a": "Ամեն ինչ, որ աղոթագրքերում կա, եկավ ավելի ուշ։ Եվ որոշակի ժամերի կանոնը ծառայում է աղոթքին՝ առանց այն սպառելու. Առաքյալի <em>անդադար աղոթեցեք</em>-ը (Ա Թեսաղոնիկեցիս 5:17) ավելի լայն չափն է, իսկ սուրբ Հովհաննես Կասիանոսը, եգիպտացի հայրերին արձանագրելով, դա ասում է կտրուկ։",
"k071c623f": "Կանոնի ձևերը",
"k28364d47": "Սրանք են աշխարհականի կանոնի սովորական ձևերը՝ դասավորված ըստ այն բանի, թե օրվանից որքան է պահանջում յուրաքանչյուրը։ Սա սանդուղք չէ, որով բարձրանում են. առաջինը այն է, ինչ հեսիքաստ հայրերը նկարագրում են որպես ամբողջ աղոթք, և ինչ ամենահեռուն գնացածներին տրվում է ամեն գրվածի փոխարեն։ <strong>Որն է ձեզ վերաբերում՝ ձեր հոգևոր հոր հարցն է։</strong>",
"kf8b6b4bc": "Աղոթք առանց որոշակի ժամերի &middot; երբ ոչ ժամանակ կա, ոչ գիրք, ոչ լռություն",
"k491be6c4": "<em>Տեր Հիսուս Քրիստոս, Որդի Աստծո, ողորմիր ինձ՝ մեղավորիս։</em> Որտեղ և սա շատ է, Հայրերը թույլ են տալիս ավելի կարճ ձևեր՝ <em>Տեր Հիսուս Քրիստոս, ողորմիր ինձ</em>, կամ պարզապես <em>Տեր, ողորմիր</em>։ Նրան պետք չէ ոչ գիրք, ոչ կանգնել, ոչ ձայն, և կարելի է կրել աշխատանքային օրվա միջով։ Առաջինն է կանգնած, որովհետև գոյատևում է ամեն հանգամանքում, ոչ թե որովհետև այստեղ եղածի ամենափոքրն է։",
"k2d14e1b1": "Կարճ կանոն որոշակի ժամերին &middot; Դիդաքե",
"k25c1035a": "Որոշակի աղոթքներ՝ միացած օրվա ընթացքում շարունակվող աղոթքին &middot; նրանց համար, որոնց աշխատանքը ավելիի տեղ չի թողնում",
"k5cacd522": "Սուրբ Սերաֆիմը այն տվեց բանվորներին և ընտանիքի հայրերին, որոնք չէին կարող ավելի լիակատար աղոթքները պահել, և չհամարեց այն զիջում, որից պետք է աճելով դուրս գալ։",
"kc0703990": "Առավոտյան աղոթքները վեր կենալիս և երեկոյանները քնից առաջ՝ ասված ուշադրությամբ և ոչ շտապ։ Սուրբ Թեոփան Մենակյացը դրանք միանգամայն բավարար էր համարում սկսնակ աշխարհականի համար։",
"k030dfcd7": "Ժամերգությունների օրական շրջանը &middot; որտեղ օրը թույլ է տալիս",
"k129ba7c3": "Կարճ ժամերգությունները օրվա ընթացքում՝ Առաջին ժամից մինչև Հանգստյան ժամ։ Դիդաքեի երեք ամենօրյա աղոթքները այս շրջանի սերմն են. լրիվ ժամերը տրված են Ժամագրքում։",
"k6ca85803": "Առիթային կանոն &middot; Խորհուրդներն ընդունելուց առաջ",
"kc26de5d2": "Ճամփորդությունը, հիվանդությունը, գիշերային աշխատանքը, փոքր երեխաները, վիշտը և հյուծվածությունը՝ բոլորն ընդհատում են կանոնը։ Վերևի տեքստերից երկուսը ուղղակիորեն վերաբերում են դրան։ Դիդաքեն իր կանոնը չի ներկայացնում որպես ամեն ինչ կամ ոչինչ. որտեղ ամբողջ լուծը չի կարող կրվել՝ \"ինչ կարող ես, այն արա\"։ Իսկ Կասիանոսը հանդիմանում է նրանց, ովքեր իրենց աղոթքը հաշվում են միայն ծունկ խոնարհելու ժամերով, ինչը այդ ժամերից դուրս եղած աղոթքը հաշվի մեջ է մտցնում, ոչ թե դուրս հանում։",
"k892d0484": "Պատրաստության կարգը իրական բարիք է և իրական ժառանգություն։ Բայց այն չէ, ինչ մարդուն ընդունելու ընդունակ է դարձնում։ Սուրբ Հովհաննես Ոսկեբերանը վերցնում է հարցը՝ որքան հաճախ և որքան, և հրաժարվում է դրան այդ բառերով պատասխանել.",
"k74472bee": "Չափանիշը, որ նա անվանում է, խղճի վիճակն է, ոչ թե թիվ։ Սուրբ Հովհաննես Կասիանոսը մյուս կեսին անդրադառնում է գլխի վերնագրի ներքո, որը դա ասում է պարզ. <em>որ թեև խոստովանում ենք, թե չենք կարող առանց մեղքի լինել, այնուամենայնիվ չպետք է հեռու մնանք Տիրոջ Հաղորդությունից։</em>",
"k89f08ec2": "Անարժանության զգացումից հեռու մնալը, փաստում է նա, ինքնին ավելի մեծ հանդգնություն է. ով հեռու է մնում, մինչև արժանի դառնա, ենթադրում է, թե ուրիշ օր արժանի կլիներ։ Խորհուրդները մաքուրների վարձատրություն չեն, այլ, ըստ նրա խոսքի, մեզ սուրբ և մաքուր կդարձնեին հենց ընդունելով դրանք։",
"ke31bdf96": "Սա չափի իջեցում չէ։ Սա հենց չափն է, և Եկեղեցին այն դնում է մոտեցող յուրաքանչյուրի բերանում.",
"kfbddc832": "Առաքյալի սեփական խոսքերն են՝ <em>Քրիստոս Հիսուսը եկավ աշխարհ՝ մեղավորներին փրկելու, որոնցից առաջինը ես եմ</em>, և Եկեղեցին դրանք չթողեց թղթում. վերցրեց ժամերգության մեջ և տվեց ամեն հաղորդվողի՝ առաջին դեմքով ասելու, այն օրը, երբ ընդունում է։ Սուրբերը նրանք են, ովքեր այդ նախադասությունն ասացին և անկեղծորեն ասացին, ոչ թե նրանք, ովքեր հասան մի կետի, որտեղ այն դադարեց կիրառելի լինել։",
"kdc0a783e": "<strong>Ինչ ավանդությունն է անվանում</strong>՝ խիղճ, որ չի հանգչում չապաշխարված մեղքի մեջ, խաղաղություն մերձավորի հետ, հաղորդության պահքը, և հոգևոր հորը հնազանդություն խոստովանության հարցում։",
"keeb5d497": "<strong>Հաղորդության պահքը կանոնական է, ոչ թե սովորութային։</strong> 419 թվականի Աֆրիկյան օրենսգիրքը այն պահանջում էր և տարին մեկ բացառություն էր թույլ տալիս. Տրուլլոյի ժողովը վերցրեց այդ կանոնը և բացառությունը վերացրեց.",
"k718a2fab": "Բայց քանի որ ոչինչ մեզ չի մղում թողնել ճշգրիտ պահպանումը, որոշում ենք, որ հետևեն առաքելական և հայրապետական ավանդությանը, և սահմանում ենք, որ իրավացի չէ խզել պահքը Մեծ պահքի վերջին շաբաթվա հինգերորդ օրը և այսպես անարգել ամբողջ պահքը։",
"k2426bb65": "Ինչ կանոնները պահանջում են՝ պահքն է։ Այն նախորդ կեսգիշերից հաշվելը այն սովորույթն է, որ կրում է այն։ Որտեղ Պատարագը մատուցվում է երեկոյան՝ Նախասրբյացի, և Ծննդյան, Աստվածհայտնության, Ավագ հինգշաբթիի և Ավագ շաբաթի Պատարագները, ժամանակահատվածը սահմանում է եպիսկոպոսը, ոչ թե հաշվվում է կեսգիշերից։ Դեղերը, որ պետք է ընդունվեն, հիվանդությունը, հղիությունը, մանկությունը և խոր ծերությունը լուծվում են հոգևոր հոր կողմից։ Հարցնելը նույնը չէ, ինչ ազատված լինելը, և ոչ մեկը պատճառ չէ Բաժակից հեռու մնալու։",
"ka41be440": "Նա հրաժարվում է անապատը օրենք դարձնել՝ \"օրենք չեմ դնում ձեզ, որ լեռներն ու անապատները գրավեք, այլ որ բարի և զիջող և ողջախոհ լինեք՝ քաղաքի մեջ բնակվելով\" - և զգուշանում է, որ չկարդացվի որպես վանականներին արհամարհող, ասելով, թե խոսում է \"ոչ թե նրանց նախատելով, ովքեր լեռներն են վերցրել, այլ ողբալով նրանց, ովքեր քաղաքներում են բնակվում, որովհետև այնտեղից վտարել են առաքինությունը\"։ Վանականը իր կամքը հանձնում է ծերունուն։ Աշխարհականին տրված է նույնը հանձնելու՝ ամուսնության մեջ, աշխատանքում, որ ինքը չընտրեց, համբերության մեջ, որ տունը արժենում է, և դա նրանից պահանջվում է այնպիսի ձևով, որ ոչ մի կանոն չի կարող կանխավ տպել։",
"ke5795f78": "Պահք և խոստովանություն",
"k6602f295": "Պատրաստությունը միայն աղոթք չէ։ Չորեքշաբթի և ուրբաթ օրվա պահքը նրա ամենահին մասն է, և կանգնած է Դիդաքեի նույն գլխում, որ տալիս է աղոթքի կանոնը, - որը երկու կեսերն էլ սահմանափակում է նույն ձևով՝ զգուշացնելով ոչ թե պահքը կամ աղոթքը բաց թողնելուց, այլ որևէ մեկը <em>կեղծավորների պես</em> անելուց։",
"k78388bd9": "Հաղորդությունից առաջ խոստովանությունը որոշ ավանդություններում սպասվում է, ուրիշներում՝ ոչ, և տարբերությունը հին է, ոչ թե թուլության հարց։ Ով մի ավանդության մեջ սովորեց պատրաստվել և ապա հայտնվեց մյուսի ծխում, հեշտությամբ կարող է սովորույթի տարբերությունը իր վրա դատաստան համարել։",
}
